package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/**
 * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
 * holiday rolls to the next non-holiday weekday, any other weekday is left unchanged. Applied to
 * the effective registration date (supplied or defaulted) so every value derived from it — the
 * membership number's year, the daily create-limit bucket — sees the same adjusted day.
 */
public final class BusinessDay {

    private static final Set<LocalDate> HOLIDAYS = Set.of(
            LocalDate.of(2026, 1, 1), LocalDate.of(2026, 1, 26), LocalDate.of(2026, 4, 25),
            LocalDate.of(2026, 12, 25), LocalDate.of(2026, 12, 28));

    private BusinessDay() {
    }

    public static LocalDate roll(LocalDate date) {
        LocalDate rolled = date;
        while (rolled.getDayOfWeek() == DayOfWeek.SATURDAY
                || rolled.getDayOfWeek() == DayOfWeek.SUNDAY || HOLIDAYS.contains(rolled)) {
            rolled = rolled.plusDays(1);
        }
        return rolled;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Membership scoring for an owner. Points accrue from independent factors — 2 for a supplied email,
 * 1 for a {@code namesakeCount} of 0, 2 for a household of three or more occupants (the owner plus
 * their pets) and 3 for tenure of more than 365 days since {@code registrationDate} — and are banded
 * into a level of 1 through 4.
 */
public final class OwnerMembershipLevel {

    private OwnerMembershipLevel() {
    }

    /** The owner's membership points. */
    public static int points(Owner owner) {
        int points = 0;
        if (owner.getEmail() != null) {
            points += 2;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            points += 1;
        }
        if (1 + owner.getPets().size() >= 3) {
            points += 2;
        }
        if (tenureDays(owner) > 365) {
            points += 3;
        }
        return points;
    }

    /** The owner's membership level, 1 through 4, banded from {@link #points(Owner)}. */
    public static int of(Owner owner) {
        int points = points(owner);
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    private static long tenureDays(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        return registrationDate == null ? 0 : ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code identityKey}, the derived value all duplicate
 * detection is expressed through: {@code normalizedTelephone + '|' + (email or empty) + '|' +
 * householdId}. Two owners are duplicates only when their whole identityKey is equal, so members of
 * the same household (same householdId) with different telephones have distinct keys.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    public static String key(Owner owner) {
        return orEmpty(owner.getTelephone()) + "|" + orEmpty(owner.getEmail()) + "|"
                + orEmpty(owner.getHouseholdId());
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads and validates the request body first: a supplied registrationDate later than the server's
 * current date is rejected as 400, before any owner is built or persisted. This step owns the single
 * {@code @RequestBody} binding and republishes the body as a variable for {@link BuildOwner} to read
 * via {@code @Val}.
 */
@Validated
public class ValidateRegistrationDate {

    public void service(@Valid @RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> body)
            throws FutureRegistrationDateException {
        LocalDate registrationDate = request.getRegistrationDate();
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(registrationDate);
        }
        body.set(request);
    }
}

