10	/**
11	 * Rejects a new owner once {@value #DAILY_LIMIT} or more owners have already been created today
12	 * (by registrationDate). Runs before Save so an over-limit create is a 429, not a persisted overflow.
13	 */
14	public class EnsureDailyLimit {
15	
16	    private static final int DAILY_LIMIT = 100;
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DailyLimitExceededException {
19	        LocalDate today = owner.getRegistrationDate();
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (today.equals(existing.getRegistrationDate())) {
23	                count++;
24	            }
25	        }
26	        if (count >= DAILY_LIMIT) {
27	            throw new DailyLimitExceededException(count);
28	        }
29	    }
30	}
