7	/**
8	 * Age band derivation for an owner. The band is the owner's age in whole years at their
9	 * registration date, computed from {@code birthDate}: {@code "MINOR"} under 18, {@code "ADULT"}
10	 * from 18 to 64, and {@code "SENIOR"} at 65 or over. Returns {@code null} when either date is
11	 * absent, so the field is simply omitted from the response.
12	 */
13	public final class OwnerAgeBand {
14	
15	    private OwnerAgeBand() {
16	    }
17	
18	    /** The owner's age band at registration, or {@code null} when birthDate is not supplied. */
19	    public static String of(Owner owner) {
20	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
21	            return null;
22	        }
23	        int years = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
24	        if (years < 18) {
25	            return "MINOR";
26	        }
27	        return years < 65 ? "ADULT" : "SENIOR";
28	    }
29	}
